for n in range(1, 30):
    words = [f"w{i}" for i in range(n)]
    out = chunk_words(" ".join(words), 5, 2)
    covered = {w for chunk in out for w in chunk.split()}
    assert covered == set(words), f"{n} words: lost {set(words) - covered}"
    if len(out) > 1:
        last, prev = out[-1].split(), out[-2].split()
        assert not set(last) <= set(prev), f"{n} words: last window repeats {last}"

for size, overlap in [(4, 4), (4, 5), (0, 0), (4, -1)]:
    try:
        chunk_words("a b c", size, overlap)
    except ValueError:
        continue
    raise AssertionError(f"no ValueError for size={size}, overlap={overlap}")

