exercises.code:
def chunk_words(text, size, overlap):
    if size <= 0 or not 0 <= overlap < size:
        raise ValueError("bad size or overlap")
    words = text.split()
    if not words:
        return []
    step = size - overlap
    starts = range(0, max(len(words) - size, 1), step)
    return [" ".join(words[i:i + size]) for i in starts]

